reference_solution:
def stockSpans(prices):
    st = []
    out = []
    for p in prices:
        span = 1
        while st and st[-1][0] <= p:
            span += st.pop()[1]
        st.append((p, span))
        out.append(span)
    return out

brute_force_solution:
def stockSpans(prices):
    out = []
    for i, p in enumerate(prices):
        span = 1
        j = i - 1
        while j >= 0 and prices[j] <= p:
            span += 1
            j -= 1
        out.append(span)
    return out

